using LifeManager.Api.Domain;

namespace LifeManager.Api.Services;

public sealed class LegalAdvisorService
{
    public LegalAdvice Get(string category, string text)
    {
        var normalized = (category + " " + text).ToLowerInvariant();

        if (normalized.Contains("достав") || normalized.Contains("заказ"))
            return new("delivery", "Проблема с доставкой", "Сначала зафиксируй обещанный срок и всю переписку. После этого обращайся к продавцу или сервису письменно, чтобы осталось подтверждение требования.",
                new[] { "Проверь обещанный срок доставки в заказе, оферте или переписке.", "Сохрани чек, подтверждение оплаты и переписку с продавцом.", "Сформулируй письменное требование: что произошло и какого результата ты хочешь.", "Если вопрос не решается, проверь порядок обращения в Роспотребнадзор или другой профильный орган." },
                new LegalSource[] { new("Роспотребнадзор — защита прав потребителей", "https://www.rospotrebnadzor.ru/"), new("Государственный информационный ресурс в сфере защиты прав потребителей", "https://zpp.rospotrebnadzor.ru/") }, Disclaimer());

        if (normalized.Contains("магаз") || normalized.Contains("товар") || normalized.Contains("возврат") || normalized.Contains("брак") || normalized.Contains("гарант"))
            return new("shop", "Вопрос с товаром или магазином", "Для возврата, недостатка товара или гарантийного спора важны дата покупки, состояние товара, чек или иное подтверждение покупки и то, какое требование ты заявляешь продавцу.",
                new[] { "Сохрани чек или другое подтверждение покупки, фото товара и упаковки.", "Запиши дату, когда обнаружилась проблема, и что именно не устраивает.", "Сформулируй продавцу конкретное письменное требование и сохрани подтверждение отправки.", "Перед спором проверь актуальные правила для именно твоего типа товара и ситуации на ресурсе Роспотребнадзора." },
                new LegalSource[] { new("Роспотребнадзор — защита прав потребителей", "https://www.rospotrebnadzor.ru/"), new("ГИР ЗПП", "https://zpp.rospotrebnadzor.ru/") }, Disclaimer());

        if (normalized.Contains("работ") || normalized.Contains("зарплат") || normalized.Contains("уволь"))
            return new("work", "Трудовая ситуация", "Сохрани документы и переписку, связанные с трудовыми отношениями. Для спора важны конкретные даты, договорённости и подтверждения.",
                new[] { "Собери трудовой договор, приказы, расчётные листки и переписку.", "Зафиксируй даты и сумму спорного вопроса.", "Направь работодателю письменное обращение, если это уместно.", "Для официальной консультации проверь сервис Онлайнинспекция.рф." },
                new LegalSource[] { new("Онлайнинспекция.рф", "https://онлайнинспекция.рф/") }, Disclaimer());

        if (normalized.Contains("банк") || normalized.Contains("кредит") || normalized.Contains("карт") || normalized.Contains("списан"))
            return new("bank", "Спор с банком или финансовой организацией", "Не передавай коды подтверждения и сначала проверь операцию в официальном приложении банка. По спорным списаниям сохраняй выписки и обращения.",
                new[] { "Сохрани выписку и данные спорной операции.", "Обратись в банк через официальный канал и сохрани номер обращения.", "Если вопрос не решён, изучи порядок обращения в Банк России или к финансовому уполномоченному." },
                new LegalSource[] { new("Банк России — интернет-приёмная", "https://www.cbr.ru/reception/"), new("Финансовый уполномоченный", "https://finombudsman.ru/") }, Disclaimer());

        if (normalized.Contains("аренд") || normalized.Contains("залог") || normalized.Contains("квартир"))
            return new("rent", "Спор по аренде", "Главное — договор, подтверждение оплаты и фиксация состояния жилья. Не ограничивайся устными договорённостями, если возник спор.",
                new[] { "Подними договор и приложения к нему.", "Собери чеки или переводы по оплате и залогу.", "Сохрани фото состояния жилья и переписку.", "Сформулируй письменную позицию по спорному вопросу." }, Array.Empty<LegalSource>(), Disclaimer());

        return new(category, "Разобраться в ситуации", "Для точной инструкции нужно опираться на документы и конкретные обстоятельства. Начни с фиксации фактов и официальных источников.",
            new[] { "Коротко выпиши, что произошло и когда.", "Собери документы, чеки и переписку.", "Определи, чего именно хочешь добиться.", "Проверь профильный официальный источник перед отправкой претензии или заявления." },
            new LegalSource[] { new("Госуслуги", "https://www.gosuslugi.ru/"), new("Роспотребнадзор", "https://www.rospotrebnadzor.ru/") }, Disclaimer());
    }

    private static string Disclaimer() => "Это справочная подсказка, а не персональная юридическая консультация. Перед значимым решением проверь актуальные нормы и документы по своей ситуации.";
}
